insert into pops (clinic_id, numero, titulo, estrutura) values
  ((select id from clinics order by created_at limit 1), '021/2026', 'Hidrolipoclasia', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>HIDROLIPOCLASIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de hidrolipoclasia não aspirativa. É o uso do ultrassom terapêutico após a injeção de uma solução hipotônica (soro fisiológico + água destilada) no tecido subcutâneo. Tem o objetivo de potencializar os resultados do ultrassom focado na redução da gordura localizada, tendo uma grande significância nos seus resultados na redução de medida e contorno corporal</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Gordura localizada</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Doenças hepáticas Dislipidemia Gestante Neoplasias e metástases Lesões na pele Insuficiência renal Doenças metabólicas Patologias auditivas Isquemia Tromboflebites e varizes Implantes metálicos Área cardíaca Olhos</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, máscara e propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Soro fisiológico Aparelho Ultrassom Gel Adipômetro</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada</p>"}]}, {"id": "b8", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>A quantidade de soro fisiológico dependerá da quantidade de gordura na área a ser tratada. Assim, a quantidade ideal injetada deverá ser de responsabilidade do profissional, após uma anamnese minuciosa, feita antes do início do procedimento. HIDROLIPOCLASIA b. Fazer as medições da prega cutânea da região com o auxílio do adipômetro para saber qual ponteira será utilizada do equipamento de ultrassom focado e o comprimento da agulha a ser utilizado c. Fazer as demarcações da área com lápis esferográfico na região que será tratada Protocolo: a. Desinfecção da maca com álcool 70% b. Maca com lençol de papel descartável c. Fazer o registro fotográfico pré-procedimento d. Higienização das mãos (ver Manual de Rotinas e Procedimentos) e. Acomodar o cliente na maca durante todo o procedimento f. Realizar assepsia na região com álcool a 70% e gaze g. Aplicar a técnica da hidrolipoclasia h. Aplicar o ultrassom (3 MHz) na região a ser tratada i. Ligar o aparelho e seguir o protocolo, conforme instrução do fabricante j. Aplicar o gel na área a ser tratada k. Fazer o registro fotográfico pós-procedimento Obs.: Após o ultrassom, pode ser feita uma drenagem linfática. B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e HIDROLIPOCLASIA equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Savoia, A. et al. Noninvasive body contouring by low frequency ultrasound: a clinical study. Open reconstructive and Cosmetic Surgery, v.3, p. 11-6, 2010 Silva, R.M.V. et al. Efectos del ultrasonido de alta potencia em la adiposidad localizada. Fisioterapia, v. 37, n.2, p. 55-9, 2014 Modalidades Terapêuticas nas Disfunções Estéticas, Fábio dos Santos Borges, Ed. Phorte</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '022/2026', 'Higienização das Mãos', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>HIGIENIZAÇÃO DAS MÃOS</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever como realizar a higienização das mãos para prevenir a propagação das infecções relacionadas à assistência à saúde. Com isso, temos:</p><ul><li>Remoção da sujidade e de outros resíduos</li><li>Redução da microbiota transitória</li><li>Prevenção da transmissão de microorganismos patogênicos (infecção cruzada)</li></ul>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Antes do contato com o paciente</li><li>Antes da realização de procedimento asséptico</li><li>Após o contato com o paciente</li><li>Após o contato com as áreas próximas ao paciente (equipamentos e mobiliários)</li><li>Antes de calçar luvas e após retirar luvas</li></ul>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Não aplicável</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Torneira e lavatório ligado à rede de esgoto</li><li>Papel toalha</li><li>Sabão líquido neutro e soluções antissépticas</li><li>Lixeira provida de tampa e acionado por pedal</li></ul>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Confirmar a presença dos materiais necessários para o procedimento; 2. Retirar adornos; 3. Arregaçar a manga do vestuário até altura do cotovelo, se necessário; 4. Posicionar-se em frente a pia, sem encostar-se à mesma; 5. Abrir a torneira; 6. Molhar as mãos; 7. Fechar a torneira; 8. Aplicar na palma da mão quantidade suficiente de sabão líquido neutro para cobrir toda superfície das mãos; 9. Friccionar toda a superfície de 10 a 15 segundos: • Palma contra palma; • Palma direita sobre dorso da mão esquerda entrelaçando os dedos; • Palma esquerda sobre o dorso da mão direita, entrelaçando os dedos; • Palma contra palma com os dedos entrelaçados, friccionando os espaços interdigitais; • Parte posterior dos dedos em oposição à palma, com movimentos de vaivém; • Rotação dos polegares direito e esquerdo; • Friccionar as polpas digitais e unhas da mão direita contra a palma da mão esquerda fechada em concha fazendo movimento circular e vice-versa; • Esfregar punho esquerdo com auxílio da palma da mão direita em movimento circular e vice-versa; 10. Abrir a torneira; 11. Enxaguar as mãos no sentido dos dedos para os punhos; 12. Enxugar as mãos com papel toalha, iniciando pelas mãos e seguindo pelos punhos</p>"}, {"col1": "<p>B. Cuidados</p>", "col2": "<ul><li>Segundo a NR32 não se deve usar adornos no local de trabalho;</li><li>Manter unhas curtas e limpas e não utilizar unhas artificiais; HIGIENIZAÇÃO DAS MÃOS</li><li>Segundo a NR32 é recomendado o uso de torneiras de acionamento automático nas áreas críticas (ex. Sala de atendimento);</li><li>Nas áreas não-críticas, onde o acionamento automático e/ou automatizado da torneira não são mandatórios, fechar a torneira com auxílio do mesmo papel toalha que enxugou as mãos e desprezá-lo na lixeira de resíduos comuns;</li><li>Fixar o cartaz com as orientações para a Higienização correta das mãos, conforme Manual de Rotinas e Procedimentos, próximo às torneiras</li></ul>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>Brasil. Ministério da Saúde. Protocolo para prática de higiene das mãos em serviços de saúde. Brasília, 2013. Brasil. Ministério do Trabalho e Emprego. Portaria n° 485 de 11 de novembro de 2005. Norma regulamentadora (NR) nº 32: Segurança e saúde no trabalho em estabelecimentos de saúde</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '023/2026', 'Higienização e limpeza dos coletores e abrigos dos RSS', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>NORMAS E ROTINAS Doc. nº : 00001 Edição: Primeira HIGIENIZAÇÃO E LIMPEZA DOS COLETORES E ABRIGOS DOS RSS 25/10/2024 Revisão: 20/11/2026</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever as rotinas estabelecidas para o processo de higienização e limpeza da unidade (Local do armazenamento interno, externo, contêineres, carros de transporte)</p>"}]}, {"id": "b3", "subtitulo": "ALCANCE", "linhas": [{"col1": "", "col2": "<p>Todos os profissionais que realizam atendimentos e prestam serviços no estabelecimento, sendo colaboradores e/ou terceiros</p>"}]}, {"id": "b4", "subtitulo": "RESPONSABILIDADE", "linhas": [{"col1": "", "col2": "<p>O profissional Responsável técnico pelo estabelecimento é o responsável por garantir as condições de higiene e limpeza dos coletores e abrigos dos RSS. O profissional denominado “Responsável Legal” e/ou “Representante Legal” é o responsável por fornecer os recursos necessários aos colaboradores envolvidos no processo de higienização e limpeza dos coletores e abrigos dos RSS</p>"}]}, {"id": "b5", "subtitulo": "DEFINIÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Abrigo externo: ambiente no qual ocorre o armazenamento externo dos coletores de resíduos</li><li>Abrigo temporário: ambiente no qual ocorre o armazenamento temporário dos coletores de resíduos</li><li>Armazenamento externo: guarda dos coletores de resíduos em ambiente exclusivo, com acesso facilitado para a coleta externa</li><li>Armazenamento temporário: guarda temporária dos coletores de resíduos de serviços de saúde, em ambiente próximo aos pontos de geração, visando agilizar a coleta no interior das instalações e otimizar o deslocamento entre os pontos geradores e o ponto destinado à apresentação para coleta externa</li><li>Coletor: recipiente utilizado para acondicionar os sacos com resíduos</li><li>Coletor com rodas ou carro de coleta: recipiente com rodas utilizado para acondicionar e transportar internamente os sacos com resíduos</li></ul>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>dispositivo ou produto de uso individual utilizado pelo trabalhador, destinado à proteção de riscos suscetíveis de ameaçar a segurança e a saúde no trabalho</p><ul><li>Resíduos de serviços de saúde (RSS): todos os resíduos resultantes das atividades exercidas pelos geradores de resíduos de serviços de saúde</li><li>Resíduos de serviços de saúde do grupo A: resíduos com a possível presença de agentes biológicos que, por suas características, podem apresentar risco de infecção NORMAS E ROTINAS Doc. nº : 00001 Edição: Primeira HIGIENIZAÇÃO E LIMPEZA DOS COLETORES E ABRIGOS DOS RSS 25/10/2024 Revisão: 20/11/2026</li><li>Resíduos de serviços de saúde do grupo D: resíduos que não apresentam risco biológico, químico ou radiológico à saúde ou ao meio ambiente, podendo ser equiparados aos resíduos domiciliares</li><li>Resíduos de serviços de saúde do grupo E: resíduos perfurocortantes ou escarificantes, tais como: lâminas de barbear, agulhas, escalpes, ampolas de vidro, brocas, limas endodônticas, fios ortodônticos cortados, próteses bucais metálicas inutilizadas, pontas diamantadas, lâminas de bisturi, lancetas, tubos capilares, micropipetas, lâminas e lamínulas, espátulas e todos os utensílios de vidro quebrados no laboratório (pipetas, tubos de coleta sanguínea e placas de petri)</li><li>Transporte interno: traslado dos resíduos dos pontos de geração até o abrigo temporário ou o abrigo externo EPIs: Os equipamentos de proteção individuais recomendadas para os colaboradores envolvidos na higienização dos contêineres e recipientes dos resíduos são: ∙ Luvas de borracha (serviço de limpeza); ∙ Sapatos impermeáveis e resistentes; ∙ Gorro descartável, de proteção dos cabelos; ∙ Óculos de plástico resistente e armação flexível, incolor, com lente panorâmica, proteção lateral e válvulas de ventilação; ∙ Máscara descartável</li></ul>"}]}, {"id": "b7", "subtitulo": "MATERIAIS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<p>• Borrifador com sabão neutro • 2 Flanelas • 2 baldes para água • Borrifador com HIPOCLORITO A 1% ROTINAS DE LIMPEZA: Semanalmente pela manhã: Limpar os coletores de lixo das áreas internas do estabelecimento (ex. sala de atendimento, sala de esterilização, sanitário e recepção), conforme abaixo: ∙ Iniciar a limpeza seguindo a ordem do mais limpo para o mais sujo (de fora para dentro); ∙ Retirar o excesso de sujidade com sabão neutro e água, com auxílio da flanela; NORMAS E ROTINAS Doc. nº : 00001 Edição: Primeira HIGIENIZAÇÃO E LIMPEZA DOS COLETORES E ABRIGOS DOS RSS 25/10/2024 Revisão: 20/11/2026 ∙ Remover o excesso e secar todas as áreas do carrinho; ∙ Aplicar o HIPOCLORITO A 1% com a segunda flanela, repetindo o processo 3 vezes. Mensalmente após a coleta dos resíduos pela empresa coletora dos RSS: Limpar os coletores de lixo dos abrigos externos do estabelecimento (ex. abrigo dos resíduos infectantes e abrigo do lixo comum), conforme abaixo: ∙ Iniciar a limpeza seguindo a ordem do mais limpo para o mais sujo (de fora para dentro); ∙ Retirar o excesso de sujidade com sabão neutro e água, com auxílio da flanela; ∙ Remover o excesso e secar todas as áreas do carrinho; ∙ Aplicar o HIPOCLORITO A 1% com a segunda flanela, repetindo o processo 3 vezes</p>"}]}, {"id": "b8", "subtitulo": "FREQUÊNCIA", "linhas": [{"col1": "", "col2": "<p>∙ Lixeiras internas dos setores – semanalmente ou sempre que necessário; ∙ Lixeira externa do lixo comum - mensalmente; ∙ Abrigo Externo dos Resíduos Infectantes – mensalmente</p>"}]}, {"id": "b9", "subtitulo": "REFERÊNCIAS", "linhas": [{"col1": "", "col2": "<p>BRASIL. AGÊNCIA NACIONAL DE VIGILÂNCIA SANITÁRIA. Resolução RDC nº 222, de 28 de março de 2018. Regulamenta as Boas Práticas de Gerenciamento dos Resíduos de Serviços de Saúde e dá outras providências. Acesso em: 17 nov 2023</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '024/2026', 'Imunização', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>IMUNIZAÇÃO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Imunização é a aquisição de proteção imunológica contra doenças de caráter infeccioso. Portanto, a imunização consiste na proteção do indivíduo por meio de resistências às doenças imunopreveníveis, contra agentes infecciosos e bacterianos</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Os profissionais da área da saúde devem estar devidamente imunizados uma vez que por estarem mais expostos a agentes nocivos, possuem um risco elevado de contato com doenças infecciosas</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>A vacina da gripe está contraindicada para indivíduos alérgicos a albumina</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Vacinas disponíveis na rede pública de saúde do seu município</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Veja na tabela 1 as vacinas relatadas como importantes para os profissionais da saúde pela Anvisa (Agência Nacional de Vigilância Sanitária): TABELA 1 As doses vacinais contra Covid-19 devem seguir as orientações do Ministério da Saúde. B</p>"}]}, {"id": "b7", "subtitulo": "OBSERVAÇÕES", "linhas": [{"col1": "", "col2": "<p>• A rede pública tem as vacinas gratuitas à disposição nos Centros de Saúde. • A imunização é muito importante, é um dever do responsável técnico garantir que todo profissional que realiza atendimentos no estabelecimento esteja com seu esquema vacinal em dia e também deixar uma cópia da carteira de vacinação de cada profissional anexado ao Manual de Rotinas e Procedimentos</p>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>Brasil. Ministério da Saúde. Agência Nacional de Vigilância Sanitária. Serviços odontológicos: Prevenção e Controle de Riscos. Brasília, 2006</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '025/2026', 'Intradermoterapia Pressurizada', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>INTRADERMOTERAPIA PRESSURIZADA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de intradermoterapia pressurizada. Consiste na utilização de uma caneta de pressurização que aplica ativos por meio de jatos em altíssima velocidade, tal qual uma injeção, porém sem agulhas,</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>▪ celulite ▪ gordura localizada ▪ estrias ▪ flacidez ▪ papadas ▪ alopecia</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>▪ problemas cardíacos não controlados ▪ problemas hepáticos ▪ disfunção na tireoide ▪ dificuldades renais ▪ alergias às substâncias aplicadas ▪ gestantes ▪ lúpus ▪ infecções cutâneas próximas ▪ psoríase ▪ febre ▪ melanoma ▪ hipertensão arterial ▪ diabetes descompensada ▪ histórico de AVC ▪ fenômenos tromboembólicos ▪ uso de medicações como aspirina, varfarina, heparina, sulfonamidas, etc ▪ disfunções renais e dislipidemias</p>"}]}, {"id": "b5", "subtitulo": "NÚMERO DE SESSÕES", "linhas": [{"col1": "", "col2": "<p>A quantidade de sessões depende da avaliação e do objetivo, sempre é de forma personalizada. Os resultados já podem ser vistos após a primeira sessão e são progressivos durante o tratamento. O tempo de sessão é de aproximadamente 20 a 30 minutos e depende do tamanho da área</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente - Touca Profissional – Touca, avental, máscara e luvas INFORMAÇÕES COMPLEMENTARES: Na técnica com agulhas, deve ser respeitada a profundidade e o ângulo da agulha a depender de qual estrutura se quer atingir. Já para a técnica com a Caneta Pressurizada, o importante é escolher a quantidade de produto a ser injetado, conforme a profundidade da pele que se quer INTRADERMOTERAPIA PRESSURIZADA atingir e, muito importante, é escolher o cosmecêutico adequado para o objetivo. As canetas funcionam através de pressão que enviam um jato do ativo para dentro da pele. O dispositivo funciona por propulsão de alta velocidade, esse jato rompe o tecido epitelial da epiderme e deposita o produto A diferença entre um modelo e outro da caneta pressurizada é a quantidade de disparos e a possibilidade de adaptar seringas de diferentes tamanhos. ADVERTÊNCIAS E PRECAUÇÕES: Certifique-se de cumprir com a orientação de uso do produto. Durante a aplicação é necessário uma angulação de 90 graus entre o dispositivo injetor e a pele. Se a angulação de 90 graus entre o dispositivo injetor e a pele não for respeitada, o ativo injetado pode não ter o efeito e eficácia desejado. Certifique-se de conectar a ampola sobre o dispositivo injetor antes do uso. Disparar o dispositivo de injeção sem conectar a ampola pode causar danos ao equipamento. Descartar no lixo perfurocortante e não usar (ampola , adaptador e caps) fora do prazo de validade e/ou previamente abertos ou danificados. O carregamento inapropriado do dispositivo injetor pode causar danos ao equipamento. Evitar quedas e impactos excessivos no sistema de injeção. Quedas e impactos podem danificar o produto</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Caneta pressurizada Ativos e/ou cosmecêuticos estéreis (conforme sugestões de protocolos pelo fabricante)</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Observar os seguintes tópicos e registrar na ficha de avaliação do cliente:</p><ul><li>Alergias aos fármacos utilizados no procedimento</li><li>Hipertensão descompensada que pode ser agravada pelos fármacos ativadores da circulação sanguínea</li></ul>"}, {"col1": "<p>B. Limpeza ▪</p>", "col2": "<p>Desinfecção da maca com álcool 70% ▪ Maca com lençol de papel descartável ▪ Higienização das mãos (ver Manual de Rotinas e Procedimentos) ▪ Realizar assepsia na região INTRADERMOTERAPIA PRESSURIZADA</p>"}, {"col1": "<p>C. Procedimento</p>", "col2": "<p>Passo 1: Conecte a ampola no adaptador Passo 2: Extraia o produto do frasco original Passo 3: Selecione a dose extraída ajustando o dosímetro Passo 4: Conecte a ampola na caneta pressurizada Passo 5: Rotacione a caneta pressurizada em sentido horário até atingir a pressão Passo 6: Escolha o nível de pressurização adequado Passo 7: Selecione a dose desejada ajustando o dosímetro Passo 8: Pressione o botão de acionamento</p>"}, {"col1": "<p>D. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. Registrar todos os produtos (nome, nº do lote, fabricante) utilizados na Ficha do Cliente</p>"}, {"col1": "<p>E. Referências literárias</p>", "col2": "<p>A . Dalloz-Bourguignon. Mesoterapia uma terapêutica diferente. Editora Andrei. 1988 Ignácio Ordiz García. Tratado de Mesoterapia, Editora Alicante, 1992 Herreros FOC, Moraes AM, Velho PENF. Mesoterapia: uma revisão bibliográfica. An Bras Dermatol. 2011;86(1):96-101 Procedimentos Estéticos Minimamente Invasivos, Charles Yamaguchi, Grupo GEN Manual de Instrução Smart Press XS – Caneta Pressurizada</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '026/2026', 'Intradermoterapia', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>INTRADERMOTERAPIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de Intradermoterapia. A Intradermoterapia, também conhecida como mesoterapia, é um procedimento invasivo que consiste na aplicação, diretamente na região a ser tratada, de injeções intradérmicas de substâncias farmacológicas diluídas</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Rejuvenescimento cutâneo HLDG (celulite) e gordura localizada Flacidez tissular Alopecia masculina e feminina Melasma</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Gestação Lactação Diabetes Mellitus tipo I Antecedentes de AVE Eventos tromboembólicos Intolerância à dor AIDS LES Cardiopatias Doenças sistêmicas autoimunes</p>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>Intervalo entre as sessões de 20 a 30 dias</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca e propé Profissional – Touca, máscara, óculos de proteção, jaleco e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Agulha: 30G½ Seringa varia de acordo com a quantidade do fármaco Mesclas ou Mélanges (conforme sugestões de protocolos pelo fabricante)</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Observar os seguintes tópicos e registrar na ficha de avaliação do cliente:</p><ul><li>Alergias aos fármacos utilizados no procedimento</li><li>Hipertensão descompensada que pode ser agravada pelos fármacos ativadores da circulação sanguínea</li></ul>"}, {"col1": "<p>B. Limpeza</p>", "col2": "<p>Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Realizar assepsia na região</p>"}, {"col1": "<p>C. Misturas</p>", "col2": "<p>Misturas feitas diretamente na seringa, seguindo ordem crescente de pH Disfunção Estética: Rejuvenescimento Facial 1. Anamnese (tirar foto da área a ser tratada, classificação glogau, fototipo) 2. Classificar o grau das rugas (dinâmicas, estáticas) 3. Definir a mescla 4. Especificar o número de sessões e intervalos entre cada sessão INTRADERMOTERAPIA Protocolo: Injetar ponto a ponto em todo trajeto da ruga e ao redor das mesmas, administrando uma quantidade muito pequena de medicamento formando uma pápula, com ângulo de 15 à 45º e agulha de 4 mm. Sessões semanais por dois meses; Depois de meses, sessões a cada dias por mais dois meses. Disfunção Estética: Flacidez 1. Anamnese (foto, classificação de glogau) 2. Identificação da flacidez (tissular, muscular ou ambas) 3. Definir a mescla 4. Especificar o número de sessões e intervalos entre cada sessão Protocolo: Injetar ponto a ponto em toda área à ser tratada, administrando uma quantidade muito pequena de ativo formando uma pápula. Sessões Quinzenais – por 2 meses Depois de 2 meses, sessões a cada 30 dias por mais dois meses. Disfunção Estética: FEG (fibro edema gelóide) / Celulite 1. Anamnese (tirar foto, registrar a circunferência da área a ser tratada) 2. Classificar o grau (I, II, III, IV) e forma (edematosa, flácida, mista) 3. Definir a mescla 4. Especificar o número de sessões e intervalos entre cada sessão Protocolo: Injetar ponto a ponto, distanciando 2 cm por ponto em toda na área afetada, seguindo ângulo de 45 à 90º. Sessões semanais nos 2 primeiros meses e observar evolução. Disfunção Estética: Gordura Localizada 1. Anamnese (tirar foto, registrar a circunferência da área a ser tratada) 2. Definir a mescla 3. Especificar o número de sessões e intervalos entre cada sessão Protocolo: Injetar ponto a ponto, distanciando 2 cm por ponto em toda na área afetada, seguindo ângulo de 45 à 90º. Sessões semanais e observar evolução. Disfunção Estética: Estrias 1. Anamnese (tirar foto da área a ser tratada, comprimento e largura da estrias e localização) 2. Identificar o tipo de estria (rubra, alva) 3. Definir a mescla 4. Especificar o número de sessões e intervalos entre cada sessão Protocolo: INTRADERMOTERAPIA Injetar pápula ou por retroinjeção, ao longo de toda área afetada, seguindo ângulo de 15 à 30o com agulhas de 4 mm para aplicações em pápula ou 13 mm em caso de retroinjeções. Sessões a cada 20 dias por 2 meses e observar a evolução</p>"}, {"col1": "<p>D. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente</p>"}, {"col1": "<p>E. Referências literárias</p>", "col2": "<p>A . Dalloz-Bourguignon. Mesoterapia uma terapêutica diferente. Editora Andrei. 1988 Ignácio Ordiz García. Tratado de Mesoterapia, Editora Alicante, 1992 Herreros FOC, Moraes AM, Velho PENF. Mesoterapia: uma revisão bibliográfica. An Bras Dermatol. 2011;86(1):96-101 Procedimentos Estéticos Minimamente Invasivos, Charles Yamaguchi, Grupo</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '027/2026', 'Jato de Plasma e Eletrocautério', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>JATO DE PLASMA E ELETROCAUTÉRIO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de jato de plasma e eletrocautério. O equipamento fornece um gás ionizado que pode ser aplicado na pele através de despigmentadores elétricos, que influenciam no tipo de profundidade e raio de ação do jato de plasma. Quando aquecido, chega na pele atingindo somente a camada mais externa da pele, ativando o colágeno que irá auxiliar na cicatrização. DIFERENÇA ENTRE JATO DE PLASMA E ELETROCAUTÉRIO : Jato de Plasma : o equipamento de corrente com alta tensão e alta intensidade. Eletrocautério : o equipamento tem corrente alternada de baixa tensão e alta intensidade</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Rugas e linhas de expressão Pálpebras flácidas Clareamento de pequenas tatuagens Rejuvenescimento Cicatrizes de acne Estrias Cicatrizes</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Hiperpigmentação pós-inflamatória Pacientes com próteses grandes, marca passo, pinos metálicos Glaucoma Lentes fixas Melasma Não irradiar em pacientes que estão utilizando medicamentos ou substâncias que podem ter ação fotossensibilizadora Não utilizar o equipamento em lesões cancerígenas ou lesões sem diagnóstico Não utilizar em lesões de herpes labial</p>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>* O intervalo deve ser feito de acordo com a avaliação do profissional</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca e propé Profissional – Touca, jaleco, óculos de proteção, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Gaze Anestésico Equipamentos (caneta aplicadora) e ponteiras JATO DE PLASMA E ELETROCAUTÉRIO</p>"}]}, {"id": "b8", "subtitulo": "OBSERVAÇÕES", "linhas": [{"col1": "", "col2": "<p>Na ficha de anamnese observar se há alterações cardíacas ou de pressão</p>"}]}, {"id": "b9", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada (fazer a anamnese) Protocolo: a. Desinfecção da maca com álcool 70% b. Maca com lençol de papel descartável c. Higienização das mãos (ver Manual de Rotinas e Procedimentos) d. Acomodar o cliente na maca durante todo o procedimento e. Fazer o registro fotográfico pré-procedimento f. Passar creme anestésico antes do procedimento g. Realizar assepsia na região h. Escolher a ponteira e intensidade de acordo com o procedimento a ser realizado i. Aplicar a técnica conforme manual de instrução do equipamento j. Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Manual de instruções do fabricante do equipamento JATO DE PLASMA E ELETROCAUTÉRIO</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '028/2026', 'Limpeza de Equipamento', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº________ LIMPEZA DOS EQUIPAMENTOS</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a rotina de limpeza dos equipamentos antes de iniciar a utilização de cada equipamento e após a sua utilização em cada cliente/paciente</p>"}]}, {"id": "b3", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b4", "subtitulo": "MATERIAIS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<p>Solução antisséptica (clorexidina ou álcool 70%) Papel toalha descartável Algodão ou gaze</p>"}]}, {"id": "b5", "subtitulo": "ATENCÃO", "linhas": [{"col1": "", "col2": "<p>Sempre verificar o Manual do fabricante com os produtos permitidos para a realização da limpeza de cada equipamento</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Antes de iniciar a utilização do equipamento</p>", "col2": "<p>1. Montar o equipamento conforme manual de instruções 2. Certificar se o equipamento está desligado, com cabo de energia fora da tomada 3. Umedecer o algodão ou gaze com a solução antisséptica 4. Friccionar por no mínimo 30 segundos por toda superfície do equipamento que entrará em contato com o cliente 5. Repetir o passo 3 e 4 para todos os acessórios do equipamento 6. Ligar o aparelho e iniciar a utilização</p>"}, {"col1": "<p>B. Após a utilização do equipamento</p>", "col2": "<p>1. Desligar o equipamento 2. Retirar o cabo de energia da tomada 3. Retirar o excesso de produto (cosmético) nos acessórios com o papel toalha descartável 4. Friccionar o algodão ou gaze umedecido em solução antisséptica por toda a superfície do equipamento 5. Repetir o passo 3, 4 e 5 para todos os acessórios do equipamento nº________ LIMPEZA DOS EQUIPAMENTOS</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Manual de instrução do equipamento</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '029/2026', 'Limpeza de Pele com Extração', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>LIMPEZA DE PELE COM EXTRAÇÃO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de limpeza de pele com extração. A limpeza de pele remove as células mortas que estão presentes na camada superficial da pele . A limpeza de pele também é capaz de equilibrar o pH da epiderme, o que deixa a pele mais firme, hidratada, elástica e resulta em uma aparência mais jovem</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>• Remoção de cravos (comedões) abertos (pontos pretos) ou fechados (pontos brancos) • Remoção de miliuns • Remover as células mortas • Manter a pele macia e saudável • Ajudar no equilíbrio da pele seca, normal, oleosa e mista • Remover impurezas da pele • Remover acnes (espinhas) • Promover a limpeza dos poros • Hidratar peles secas ou ressecadas • Promove o rejuvenescimento facial • Previne rugas • Previne o envelhecimento da pele • Prepara a pele para peeling químico</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAL CONTRA-INDICAÇÃO", "linhas": [{"col1": "", "col2": "<p>Quando há acne em excesso, pois pode deixar cicatrizes, além de gerar mais inflamação e agravar o quadro de acne</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Máscara térmica (opcional) Vapor de ozônio Dermocosméticos</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Observar os seguintes tópicos e registrar na ficha de avaliação do cliente:</p><ul><li>Classificar o fototipo, biotipo e estado cutâneo do cliente B. Higienização 1. Fazer assepsia das mãos do profissional e do cliente 2. Aplicar o demaquilante no rosto, pescoço e colo do cliente e remover com algodão ou gaze embebida em água 3. Fazer esfoliação nas regiões a serem tratadas e massageá-las com movimentos suaves e circulares até o produto formar grumos, secar e sair totalmente. Retirar os resíduos do produto com gazes úmidas ou lenços umedecidos LIMPEZA DE PELE COM EXTRAÇÃO 4. Fazer emoliência usando compressas de algodão umedecidas com o amolecedor de comedões e aplicar nas regiões onde for trabalhar com as extrações, principalmente, nariz, mento e frontal. Cobrir com compressas de algodão úmidas e aplicar vapor de ozônio ou máscara térmica</li></ul>"}, {"col1": "<p>C. Aplicação da máscara térmica</p>", "col2": "<p>i. Verifique se a máscara térmica está ajustada corretamente e em bom estado de funcionamento ii. Aplique uma máscara de hidratação ou uma máscara de limpeza profunda no rosto do cliente iii. Coloque a máscara térmica sobre o rosto do cliente e ajuste a temperatura de acordo com as instruções do fabricante iv. Deixe a máscara térmica agir pelo tempo recomendado</p>"}, {"col1": "<p>D. Vapor de ozônio</p>", "col2": "<p>i. Certifique-se de que o vapor de ozônio esteja funcionando corretamente e ajuste a intensidade de acordo com as necessidades do cliente. ii. Posicione o cliente de forma confortável em frente ao vapor de ozônio. iii. Permita que o vapor de ozônio incida sobre o rosto do cliente por cerca de 5 a 10 minutos para abrir os poros e preparar a pele para a extração. E. Procedimento 5. Retirar as compressas, à medida que for fazendo as extrações 6. Ao término das extrações, utilizar o aparelho de alta frequência no rosto ou região onde foi realizada a extração, durante 5 minutos e, se necessário, usar o fulgurador do aparelho, nos locais onde houve extravasamento de líquido, pela ação bactericida e fungicida. Não encostar diretamente na pele 7. Aplicar a Loção Tônica, para equilíbrio do pH, em toda a região de tratamento 8. Aplicar em seguida uma camada de máscara calmante ou hidrante e realizar uma drenagem linfática até absorver todo o produto ou aguardar 20 (vinte) minutos e retirar 9. Finalizar com filtro solar, dependendo do tipo de pele e acabamento desejado</p>"}, {"col1": "<p>F. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. Orientar a Manutenção diária do cliente:</p><ul><li>Emulsão de Limpeza</li><li>Loção Tônica</li><li>Proteção solar, uso diário</li></ul>"}, {"col1": "<p>G. Referências literárias</p>", "col2": "<p>DRAELOS; Zoe Diana Procedimentos em dermatologia cosmética: Cosmecêuticos. Ed. 1.Rio de Janeiro Editora: ELSEVIER LIMPEZA DE PELE COM EXTRAÇÃO MACEDO; Otávio Robert Segredos da boa pele: preservação e correção. Ed. São Paulo 1998. Editora: SENAC BARATA; Eduardo A</p>"}, {"col1": "<p>F. A cosmetologia</p>", "col2": "<p>Princípios Básicos. Ed.1. São Paulo 2003. Editora: TECNOPRESS</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '030/2026', 'Limpeza do ar condicionado', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>LIMPEZA DO AR CONDICIONADO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a rotina de limpeza e manutenção do ar condicionado. INFORMAÇÕES GERAIS: De acordo com Lei nº 13. 589/2018, todos os edifícios de uso público e coletivo que possuem ambientes de ar interior climatizado artificialmente devem dispor de um Plano de Manutenção, Operação e Controle – PMOC dos respectivos sistemas de climatização, visando à eliminação ou minimização de riscos potenciais à saúde dos ocupantes. Caso o empreendimento tenha sistema de climatização com capacidade abaixo de 60.000 BTU/H, o PMOC deixa de ser obrigatório. O limite de capacidade de climatização de 60.000 BTU/H deve ser considerado levando-se em conta não apenas um ambiente, mas sim todo o sistema de climatização do estabelecimento. Logo, se houver mais de um cômodo climatizado na edificação, é preciso somar as capacidades dos aparelhos de ar-condicionado dos diversos ambientes. Os padrões, valores, parâmetros, normas e procedimentos necessários à garantia da boa qualidade do ar interior, inclusive de temperatura, umidade, velocidade, taxa de renovação e grau de pureza, são os regulamentados pela Resolução nº 9, de 16 de janeiro de 2003, da Agência Nacional de Vigilância Sanitária - ANVISA, e posteriores alterações, assim como as normas técnicas da ABNT – Associação Brasileira de Normas Técnicas</p>"}]}, {"id": "b3", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>LIMPEZA DO AR CONDICIONADO: 1) Desligue o aparelho da tomada; LIMPEZA DO AR CONDICIONADO 2) Retire o painel frontal e limpe-o com um pano macio e seco. Caso esteja muito sujo, umedeça o pano com água morna; 3) Retire o filtro do aparelho com cuidado e lave-o em água corrente (fria ou morna); 4) Utilize sabão neutro e bucha para completar a lavagem; 5) Deixe o filtro secar naturalmente ou utilize outro pano macio. Não utilizar:</p><ul><li>Polidor para limpar a área interna do ar concionado;</li><li>Produto químico;</li><li>Água quente. Obs.: Leia sempre as instruções de limpeza no manual do seu aparelho e se houver alguma recomendação específica do modelo, lá estarão todas as dicas. E não se esqueça de nunca ligar o aparelho sem os filtros. - MANUTENÇÃO DO AR CONDICIONADO: A manutenção do equipamento deve ser realizada por empresa especializada uma ou duas vezes ao ano, conforme volume de pessoas no estabelecimento. Armazenar o comprovante da realização desse serviço em pasta própria</li></ul>"}]}, {"id": "b4", "subtitulo": "REFERÊNCIAS", "linhas": [{"col1": "", "col2": "<p>Lei nº 13. 589/2018 Resolução nº 9, de 16 de janeiro de 2003</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '031/2026', 'Limpeza e Desinfecção', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº___________ LIMPEZA E DESINFECÇÃO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a rotina de limpeza e desinfecção do ambiente e dos utensílios utilizados durante os procedimentos em cada cliente/paciente. Descrever também a limpeza concorrente e terminal</p>"}]}, {"id": "b3", "subtitulo": "DEFINIÇÕES", "linhas": [{"col1": "", "col2": "<p>• MATERIAL CRÍTICO: são produtos para a saúde utilizados em procedimentos invasivos com penetração de pele e mucosas adjacentes, tecidos subepteliais, e sistema vascular, incluindo também todos os produtos para saúde que estejam diretamente conectados com esses sistemas. Ex.: Cureta, pinças O Ministério da Saúde classifica como artigos críticos os instrumentos de natureza perfurocortante que podem ocasionar a penetração através da pele e mucosas e, portanto, necessitam de tratamento específico (esterilização) após o uso, para se tornarem livres de quaisquer microorganismos capazes de transmitir doenças. Os instrumentos de metal esterilizados devem ser guardados, em local limpo e seco e constar na embalagem a data da esterilização e a data de validade (de 7 dias ou conforme orientação da vigilância sanitária local). nº___________ LIMPEZA E DESINFECÇÃO • MATERIAL SEMI-CRÍTICO: produtos que entram em contato com pele não íntegra ou mucosas íntegras colonizadas. Ex.: Inaladores • MATERIAL NÃO CRÍTICO: produtos que entram em contato com pele íntegra ou não entram em contato com o paciente. Ex.: Recipiente, espátula, termômetro. Os artigos não críticos de uso permanente, como: tigelas de vidro, silicone ou plástico devem ser lavados com água e sabão a cada atendimento. O fluxograma dos passos sequenciais do processamento dos artigos está disponível no ANEXO I</p>"}]}, {"id": "b4", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<p>Solução antisséptica (álcool 70%) Solução Desinfetante Papel toalha descartável Algodão ou gaze Luvas grossas Detergente Solução desincrostante (opcional) E.P.I.s Escova de plástico Recipiente com solução detergente (bacia, balde, Mop)</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. PROCEDIMENTO</p>", "col2": "<p>PARA LIMPEZA DO AMBIENTE: LIMPEZA DO AMBIENTE: nº___________ LIMPEZA E DESINFECÇÃO Princípios que norteiam o procedimento de higienização eficaz: i. Limpar no sentido da área mais limpa para a mais suja; ii. Da área menos contaminada para a mais contaminada; iii. De cima para baixo (ação da gravidade); iv. Remover as sujidades sempre no mesmo sentido e direção. Os procedimentos de higienização devem ser realizados nas seguintes áreas e superfícies fixas: PISO Periodicidade: Diariamente e sempre que necessário Procedimentos: - varrer, retirando todos os resíduos existentes; - espalhar água e sabão em toda a superfície com auxílio de um pano; - enxaguar o pano em água limpa e retirar o sabão; - diluir a solução desinfetante conforme orientação do fabricante, e aplicar em toda superfície com auxílio de um pano limpo; - deixar secar. VASO SANITÁRIO Periodicidade: Diariamente e sempre que apresentar-se sujo. Procedimento: - acionar a descarga; - iniciar a lavagem externa do vaso sanitário com água e sabão; - proceder à lavagem interna, com auxílio de uma escova de cabo longo, esfregando todos os cantos visíveis; - acionar a descarga para enxaguar; - colocar solução desinfetante dentro do vaso sanitário. MOBILIÁRIO E ADORNOS Periodicidade: Diariamente, sempre que houver respingo de algum produto. nº___________ LIMPEZA E DESINFECÇÃO Procedimento: - limpar com água e sabão, com auxílio de um pano limpo; - enxaguar o pano em água limpa e retirar o sabão; - aplicar solução desinfetante com auxílio de um pano limpo; - deixar secar. PORTAS E PAREDES Periodicidade: uma vez por semana e sempre que necessário Procedimento: - limpar com água e sabão, com auxílio de um pano limpo; - enxaguar o pano em água limpa e retirar o sabão; - aplicar solução desinfetante com auxílio de um pano limpo; - deixar secar</p>"}]}, {"id": "b7", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>A diluição do desinfetante deve seguir orientação do fabricante</p>"}]}, {"id": "b8", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Todos os produtos utilizados no processo de limpeza e desinfecção devem estar devidamente regularizados na ANVISA (Agência Nacional de Vigilância Sanitária)</p>"}]}, {"id": "b9", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>A escolha dos saneantes deve ser baseado no Quadro I, disponível no ANEXO II</p>"}, {"col1": "<p>B. PROCEDIMENTO</p>", "col2": "<p>PARA LIMPEZA DOS UTENSÍLIOS: LIMPEZA DOS ARTIGOS (utensílios e instrumentais): A limpeza consiste na lavagem, enxágue e secagem do material, com objetivo de remover totalmente os detritos e sujidade dos artigos (ex. tigelas de vidro, plástico ou de aço inox). A limpeza dos artigos é feita por processo manual, utilizando-se as mãos. Limpeza Manual</p>"}]}, {"id": "b10", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>O1. Imergir o material em solução de água com substância detergente e ou nº___________ LIMPEZA E DESINFECÇÃO desincrustante (para promover a remoção dos detritos orgânicos). 2. Proceder à lavagem do material através de fricção. 3. Após a lavagem do material deve-se efetuar um cuidadoso enxague, para remover completamente os resíduos de detergente. 4. Enxugar os artigos. 5. Realizar a desinfecção dos materiais Limpeza Mecânica (lavadora ultrassônica): As lavadoras ultrassônicas propiciam uma limpeza em profundidade. Um núcleo gasoso gera minúsculas bolhas que se expandem até se tornarem instáveis e explodirem. Essa implosão produz áreas de vácuo que “puxam” as sujidades, desincrustando-as dos materiais. Quando associado à ação do detergente e do calor, o ultrassom possibilita a remoção até das sujidades mais aderentes, em locais que a escovação manual não alcança. Procedimento O1. Colocar os instrumentos abertos na lavadora 2. Colocar detergente na máquina 3. Ligar a lavadora conforme orientação do fabricante 4. Após a lavagem do material, deve-se efetuar um nº___________ LIMPEZA E DESINFECÇÃO cuidadoso enxague, para remover completamente os resíduos de detergente 5. Enxugar cuidadosamente cada peça DESINFECÇÃO: Refere-se ao método capaz de eliminar a maior parte dos germes patogênicos, com exceção dos esporos (germe mais resistente), descrito a seguir:</p><ul><li>Material necessário para desinfecção com álcool a 70% - álcool a 70% - algodão ou gaze - luvas de procedimento e limpeza</li><li>Procedimentos: - friccionar o algodão ou gaze com álcool a 70% por 30 segundos de contato e deixar secar; - repetir a operação por 03 vezes</li></ul>"}]}, {"id": "b11", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>A diluição do desinfetante deve seguir orientação do fabricante</p>"}]}, {"id": "b12", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Todos os produtos utilizados no processo de limpeza e desinfecção devem estar devidamente regularizados na ANVISA (Agência Nacional de Vigilância Sanitária)</p>"}, {"col1": "<p>C. LIMPEZA</p>", "col2": "<p>CONCORRENTE</p>"}]}, {"id": "b13", "subtitulo": "RESPONSÁVEL", "linhas": [{"col1": "", "col2": "<p>auxiliar de serviços gerais Quando: ao início ou término das atividades nº___________ LIMPEZA E DESINFECÇÃO</p>"}]}, {"id": "b14", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>manter o ambiente propício às condições de trabalho e evitar o fluxo de microrganismo Monitoramento: Todos os profissionais Material: Equipamentos de proteção individual (EPIs) e Materiais para limpeza Limpeza concorrente: é o processo de limpeza diária de todas as áreas do estabeelcimento, objetivando a manutenção do asseio, o abastecimento e a reposição dos materiais de consumo diário (sabonete líquido, papel higiênico, papel toalha interfoliado etc.) e a coleta de resíduos de acordo com a sua classificação, proporcionando ambientes limpos e agradáveis. Procedimento: 1. Deve avaliar os horários de fluxo de cada setor; 2. Iniciar pelo setor de menor risco de vinculação de microrganismos; 3. Os corredores devem ser limpos uma metade e depois a outra; 4. Não realizar varreduras a seco; 5. Iniciar com as retiradas do lixo; 6. Organização do ambiente e reposição de materiais; 7. Limpeza de superfícies, 8. Limpeza dos pisos; 9. Limpar bebedouros; 10. Limpar instalações sanitárias; 11. Registrar no ANEXO disponível no Manual de Rotinas e Procedimentos</p>"}, {"col1": "<p>D. LIMPEZA</p>", "col2": "<p>TERMINAL</p>"}]}, {"id": "b15", "subtitulo": "RESPONSÁVEL", "linhas": [{"col1": "", "col2": "<p>auxiliar de serviços gerais Quando: a cada 15 dias</p>"}]}, {"id": "b16", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>manter o ambiente adequado para o trabalho e livre de microrganismos patógenos Monitoramento: Todos os profissionais nº___________ LIMPEZA E DESINFECÇÃO Material: Equipamentos de proteção individual (EPIs) e Materiais para limpeza Limpeza terminal: A limpeza terminal é uma limpeza mais completa. Deve ser programa devido o fluxo do ambiente. O procedimento inclui a limpeza de paredes, pisos, teto, equipamentos, macas, mesas de refeição, armários, bancadas, janelas, vidros, portas, peitoris e luminárias. Procedimento: 1. Comunicar aos profissionais sobre o horário de limpeza; 2. Observar os POP’s de limpeza de janelas, paredes, pisos; 3. Reunir os materiais a serem utilizados; 4. Organizar o ambiente, guardar papéis e objetos que não podem ser molhados; 5. Retirar os lixos; 6. Levantar imobiliários; 7. Registrar no ANEXO disponóvel no Manual de Rotinas e Procedimentos</p>"}, {"col1": "<p>E. FLUXOGRAMA</p>", "col2": "<p>O Fluxograma dos passos sequenciais do processamento de superfícies, quando contaminadas por matéria orgânica está disponível no ANEXO III</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '032/2026', 'Limpeza Transdutores de Ultrassom', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº________ LIMPEZA TRANSDUTORES DE ULTRASSOM</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever o processo de limpeza dos Transdutores da Ultrassom antes de iniciar a utilização de cada equipamento e após a sua utilização em cada paciente. A limpeza e desinfecção adequadas dos transdutores de ultrassom são essenciais para prevenir a disseminação de infecções</p>"}]}, {"id": "b3", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b4", "subtitulo": "MATERIAIS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<p>1. Solução de Limpeza Enzimática:</p><ul><li>Utilizada para remover sujidades orgânicas, como gel de ultrassom e fluidos biológicos. A solução enzimática ajuda a quebrar esses resíduos. 2. Solução Desinfetante de Alto Nível (HLD):</li><li>Desinfetante aprovado para uso em dispositivos médicos semicríticos, como transdutores de ultrassom. O desinfetante de alto nível é necessário para garantir a eliminação de microorganismos patogênicos. Siga as instruções do fabricante para diluição e uso. 3. Toalhas ou Panos Descartáveis:</li><li>Usados para aplicar as soluções de limpeza e desinfecção, bem como para secar o transdutor após o procedimento. 4. Escova Macia:</li><li>Pode ser necessária para a limpeza de áreas de difícil acesso no nº________ LIMPEZA TRANSDUTORES DE ULTRASSOM transdutor. Certifique-se de usar uma escova que não danifique o equipamento. 5. Luvas Descartáveis:</li><li>Essenciais para proteger as mãos durante o manuseio de produtos químicos e durante o processo de limpeza e desinfecção. 6. Recipientes para Imersão:</li><li>Utilizados para imergir o transdutor nas soluções de limpeza e desinfecção. Os recipientes devem ser grandes o suficiente para garantir a imersão completa do transdutor. 7. Água Potável:</li><li>Utilizada para enxaguar o transdutor após a aplicação das soluções de limpeza e desinfecção. 8. Registro e Etiquetas:</li><li>Documentação para manter um registro detalhado do processo de limpeza e desinfecção. Etiquetas podem ser usadas para indicar a data da última desinfecção. 9. Produtos Específicos do Fabricante:</li><li>Alguns fabricantes podem recomendar produtos específicos para limpeza e desinfecção de seus transdutores. Certifique-se de seguir as orientações fornecidas pelo fabricante. nº________ LIMPEZA TRANSDUTORES DE ULTRASSOM</li></ul>"}]}, {"id": "b5", "subtitulo": "ATENCÃO", "linhas": [{"col1": "", "col2": "<p>Sempre verificar o Manual do fabricante com os produtos permitidos para a realização da limpeza de cada equipamento</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>a. Desligue o Equipamento: a. Desligue o equipamento de ultrassom e desconecte o transdutor. b. Remoção de Gel e Sujidades: a. Utilizando uma toalha ou papel descartável, remova o excesso de gel e sujidades visíveis do transdutor. c. Limpeza Enzimática: a. Prepare a solução enzimática de acordo com as instruções do fabricante. b. Mergulhe o transdutor na solução enzimática por um período de tempo especificado. c. Use uma escova macia para limpar áreas de difícil acesso. d. Enxágue: a. Enxágue completamente o transdutor com água potável para remover resíduos da solução enzimática. e. Secagem: a. Seque o transdutor com uma toalha ou pano descartável. Certifique-se de que o transdutor esteja completamente seco. f. Desinfecção de Alto Nível (HLD): a. Prepare a solução desinfetante de alto nível, seguindo as nº________ LIMPEZA TRANSDUTORES DE ULTRASSOM instruções do fabricante. b. Mergulhe o transdutor na solução por um tempo especificado, garantindo uma imersão completa. g. Enxágue Final: a. Enxágue novamente o transdutor com água potável para remover resíduos da solução desinfetante. h. Secagem Final: a. Permita que o transdutor seque completamente antes de reconectar ao equipamento. i. Reconexão e Verificação: a. Reconecte o transdutor ao equipamento de ultrassom. b. Realize verificações de funcionalidade conforme recomendado pelo fabricante. j. Registro: a. Mantenha um registro detalhado de cada processo de limpeza e desinfecção, incluindo datas, produtos utilizados e quem realizou o procedimento</p>"}, {"col1": "<p>B. Considerações importantes</p>", "col2": "<p>1</p>"}]}, {"id": "b7", "subtitulo": "FREQUÊNCIA", "linhas": [{"col1": "", "col2": "<p>A frequência da limpeza e desinfecção depende do uso do transdutor. Recomenda-se seguir as diretrizes do fabricante. 2. Treinamento: Pessoal responsável pela limpeza e desinfecção deve ser devidamente treinado para nº________ LIMPEZA TRANSDUTORES DE ULTRASSOM realizar o procedimento de forma eficaz e segura. 3. Produtos Aprovados: Utilize apenas produtos aprovados pelo fabricante do transdutor para evitar danos e garantir a eficácia</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Manual de instrução do equipamento. Pellizzari RM, et al. Reprocessing of Ultrasound Transducers: Implementation of Updated Guidelines. 2018. O''Brien Jr WD, et al. Guidance for Ultrasound Transducer Cleaning and Disinfection: An Update from the AIUM/SDMS. 2015</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '033/2026', 'MANUAL DE ROTINAS E PROCEDIMENTOS_2024', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>Código POP01 Edição Primeira TERAPIA CAPILAR Data 25/102024 1 –</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Este documento tem por objetivo ajudar o profissional legalmente habilitado a realizar a avaliação, estabelecer o procedimento e escolher os recursos utilizados nas diversas disfunções capilares, do couro cabeludo e da haste capilar, de acordo com as características específicas de cada cliente, respeitando a individualidade de cada um e os princípios da ética. 2 –</p>"}]}, {"id": "b3", "subtitulo": "ALCANCE", "linhas": [{"col1": "", "col2": "<p>Este POP aplica-se a todos profissionais legalmente habilitados e qualificados na Terapia Capilar. 3 – REFERÊNCIA: Especialização lato sensu em enfermagem dermatológica e estética. Terapia capilar: Uma abordagem inter e multidisciplinar. 1ª edição. São Paulo. Red Publicações, 2017. 4 –</p>"}]}, {"id": "b4", "subtitulo": "RESPONSABILIDADES", "linhas": [{"col1": "", "col2": "<p>Manuseio - O profissional habilitado e qualificado será o responsável pela escolha do protocolo e pela realização do procedimento. Quando tiver uma equipe, os profissionais também devem ser legalmente habilitados e qualificados para a realização do procedimento. Manutenção dos equipamentos – O profissional Responsável Técnico e o profissional habilitado que realizará o procedimento são os responsáveis por assegurar a manutenção e/ou calibração periódica de rotina que deve ser realizada por empresas licenciadas pelo fabricante do equipamento, se aplicável. Legalidade – O profissional Responsável Técnico e o profissional habilitado que realizará o procedimento são os responsáveis por assegurar que todos os equipamentos e produtos utilizados nos procedimento estejam devidamente regularizados na ANVISA (Agência Nacional de Vigilância Sanitária). sem autorização prévia. Código POP01 Edição Primeira TERAPIA CAPILAR 5 – ELETROTERAPIA E OUTROS RECURSOS UTILIZADOS NA TERAPIA CAPILAR: RECURSOS AÇÃO a. Alta frequência (modo direto com afastamento ou indireto/saturação) Vasodilatador; oxigenante; estimulante b. Carboxiterapia Aumento da oxigenação e circulação sanguínea c. Radiofrequência Incremento do fluxo sanguíneo, no metabolismo do crescimento do pelo e nos nutrientes do bulbo piloso d. Iontoforese e Eletroporação Aumento da permeação dos princípios ativos e. Microcorrentes Aumento da produção de ATP, transporte ativo de aminoácidos (síntese de proteínas), oxigenação, absorção de nutrientes e cicatrização f. Laser vermelho Ativa a circulação sanguínea periférica g. Laser infravermelho Ativa a circulação profunda h. LED âmbar Síntese de aminoácidos na organela ribossômica, aumentando a nutrição do bulbo i. LED azul Fungicida, diminui a oleosidade e aumenta a hidratação j. Alta frequência (modo direto sem afastamento) Calmante, cicatrizante k. Desincruste Retirada do excesso de sebo l. Mesoterapia (intradermoterapia) Consiste na infiltração de substâncias no couro cabeludo por meio de microinfiltrações realizadas com o dispositivo/equipamento aprovado pela ANVISA m. Microagulhamento (terapia de indução de colágeno) A técnica é utilizada com o roller ou com o dispositivo/equipamento aprovado pela ANVISA 6 – TIPOS DE PROTOCOLOS:</p><ul><li>Protocolos cosméticos (ex. cafeína, argan, macadâmia, etc)</li><li>Protocolos cosméticos e alta frequência associada</li><li>Protocolos com eletroterapia e outros recursos associados (ex. microcorrente e argila; corrente direta (galvânica) e argila verde; carboxiterapia e laser, etc) Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. 7 – EQUIPAMENTOS DE PROTEÇÃO INDIVIDUAL (EPI’s): Cliente: propé, máscara descartável Profissional: touca, propé, óculos de proteção, máscara descartável, avental descartável, óculos de proteção, luva descartável 8 –</li></ul>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>O profissional estabelecerá o intervalo de acordo com as característica de cada cliente. 9 – MATERIAIS NECESSÁRIOS PARA A REALIZAÇÃO DOS PROCEDIMENTO: Álcool 70%, algodão ou gaze, produtos, equipamentos e outros materiais de acordo com o protocolo escolhido. 10 – PROCEDIMENTO (PASSO A PASSO) DA TERAPIA CAPILAR: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Realizar a anamnese ou avaliação diagnóstica 5. Fazer o registro fotográfico pré-procedimento 6. Higienização do couro cabeludo e da haste capilar: são ações usadas para eliminar a sujidade tanto no couro cabeludo como na haste capilar: a. Alta</p>"}]}, {"id": "b6", "subtitulo": "FREQUÊNCIA", "linhas": [{"col1": "", "col2": "<p>aplicar o eletrodo pente com o cabelo seco (efeito bactericida e fungicida) b. Desincrustação de acordo com as disfunções apresentadas no couro cabeludo c. Esfoliação: para remover células mortas, placas de caspas, seborreia, etc d. Lavar e condicionar os cabelos. A lavagem deve ser iniciada pelo couro cabeludo, com aplicação de xampu apropriado. O condicionador deve ser aplicado na extensão do fio do cabelo sem atingir o couro cabeludo, apenas Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. com o objetivo de desembaraçar os fios. Não deixar nenhum resíduo desses produtos nos cabelos 7. Aplicar o protocolo/recurso escolhido de acordo com a disfunção do cliente (com os cabelos limpos, íntegros, úmidos ou quase secos). 8. Finalização: a. Com produtos como tônicos no couro cabeludo e hidratantes que não precisem de enxague, se não for usar secador b. Secar os cabelos: nesse caso, usar produtos finalizantes com ação térmica para o fio, a fim de proteger a haste capilar antes do uso do secador c. Aplicar leave in ou reparador de pontas d. Fazer orientação cosmética para o uso diário (home care) 9. Tirar foto pós- procedimento e arquivar na ficha/prontuário do cliente 10. Definir o número de sessões e intervalos entre as sessões I. PROTOCOLO COSMÉTICO COM CAFEÍNA: Função: alopecia androgenética 1. Realizar desintoxicação: 1 vez por semana a. Higienização com sabonete neutro b. Esfoliação com gel esfoliante c. Máscara com argila verde com água filtrada por 15 minutos d. Lavagem com xampu de cafeína a 0,005% e. Aplicação de tônico capilar de cafeína a 0,005% f. Finalização com filtro solar II. PROTOCOLO COSMÉTICO COM ÓLEOS VEGETAIS (ARGAN E MACADÂMIA): Função: hidratação do fio 1. Lavar os cabelos com xampu adequado 2. Aplicar máscara capilar com óleo vegetal de macadâmia e argan nos fios. Ocluir com filme osmótico e deixar agir de a minutos 3. Retirar a máscara com água 4. Aplicar um finalizador leave in ou um creme sem enxague III. PROTOCOLO COSMÉTICO COM QUERATINA: Função: reconstrução capilar ou cauterização com queratina 1. Lavar os cabelos com xampu antirresíduos Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. 2. Aplicar um produto à base de queratina com um protetor termoativado 3. Secar os cabelos com secador e aplicar a prancha 4. Esperar esfriar e lavar o cabelo com condicionador 5. Aplicar um finalizador leave in ou um creme sem enxague IV. PROTOCOLO COSMÉTICO COM ARGILA VERDE E ALTA</p>"}]}, {"id": "b7", "subtitulo": "FREQUÊNCIA", "linhas": [{"col1": "", "col2": "<p>Função: prevenção da queda, controle da oleosidade e antiseborreico 1. Aplicar alta frequência modo direto de 5 a 8 minutos no cabelo seco 2. Higienizar e esfoliar o couro cabeludo 3. Aplicar máscara de argila verde com loção tônica adstringente e ocluir com filme osmótico ou papel laminado por minutos 4. Lavar o cabelo com xampu antiqueda e/ou antiseborreico 5. Aplicar um tônico capilar antiqueda e finalizador com leave in, se necessário</p>"}, {"col1": "<p>V. PROTOCOLO</p>", "col2": "<p>COM MICROCORRENTE E ARGILA: Função: dermatite seborreica 1. Aplicar alta frequência modo direto sem afastamento de 3 a 8 minutos no cabelo seco 2. Lavar o cabelo com xampu adequado 3. Aplicar microcorrente no couro cabeludo 4. Aplicar a máscara de argila branca com loção calmante ou cicatrizante no couro cabeludo. Deixar agir por minutos e lavar em seguida 5. Aplicar um leave in, se necessário VI. PROTOCOLO COM CORRENTE DIRETA (GALVÂNICA) E ARGILA VERDE: desincruste Função: antiseborreico, caspa intensa e resíduos químicos 1. Aplicar alta frequência de 5 a 8 minutos no cabelo seco 2. Lavar o cabelo com xampu adequado e aplicar condicionador apenas nas pontas 3. Aplicar o desincruste em todo o couro cabeludo 4. Aplicar a argila verde com água destilada ou loção adstringente. Ocluir por 20 minutos. Repetir a lavagem fazendo leve esfoliação com a própria argila 5. Hidratar o fio , se necessário Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. 6. Aplicar um tônico capilar no couro cabeludo e finalizar com leave in na haste capilar VII. PROTOCOLO COM RADIOFREQUÊNCIA: Função: alopecia areata e androgenética 1. Aplicar alta frequência com eletrodo pente no modo direto de 5 a 8 minutos no cabelo seco 2. Lavar o cabelo com xampu adequado e esfoliar 3. Aplicar radiofrequência 4. Finalizar com fluido ou loção capilar com fatores de crescimento FGF e VEGF e massagem estimulante 5. Aplicar um leave in , se for necessário VIII. PROTOCOLO COM LASERTERAPIA ASSOCIADO COM MICROAGULHAMENTO: Função: alopecia areata e androgenética 1. Lavar o cabelo com xampu e massagem no couro cabeludo com o uso do esfoliante 2. Aplicar alta frequência modo direto com afastamento de 5 a 8 minutos no cabelo seco 3. Realizar o microagulhamento (tamanho da agulha: 0,2 ou 0,3 mm) com indução de fatores de crescimento ou iontoforese 4. Laserterapia (laser vermelho e infravermelho) 5. Massagem no couro cabeludo, pescoço, clavícula e trapézio 6. Aplicar um leave in , se for necessário IX. PROTOCOLO COM LASERTERAPIA ASSOCIADO COM RADIOFREQUÊNCIA: Função: tratamento antiqueda 1. Aplicar alta frequência modo direto sem afastamento de 3 a 8 minutos no cabelo seco 2. Lavar os cabelos com xampu antiqueda e esfoliar o couro cabeludo 3. Aplicar radiofrequência 4. Aplicar laser vermelho e infravermelho 5. Aplicar um tônico fotobioestimulante e, logo após, o led âmbar Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. 6. Finalizar com massagem estimulante (podendo associar a utilização da alta frequência no método indireto) 7. Aplicar um leave in , se for necessário</p>"}, {"col1": "<p>X. PROTOCOLO</p>", "col2": "<p>COM MICROAGULHAMENTO: Função: estímulo crescimento dos fios 1. Aplicar alta frequência modo direto com afastamento no cabelo seco 2. Lavar o cabelo com xampu adequado 3. Realizar o microagulhamento para estimulação e aumento da penetração dos produtos usados (tamanho da agulha: 0,5 mm) 4. Durante o microagulhamento, aplicar uma solução com ativos indutores do crescimento capilar (fatores de crescimento, etc) 5. Finalize com sérum, se for necessário XI. PROTOCOLO COM CARBOXITERAPIA E LASER: Função: queda e alopecias 1. Aplicar alta frequência modo direto com afastamento de 5 a 8 minutos no cabelo seco 2. Lavar o cabelo com xampu antiqueda e esfoliar o couro cabeludo 3. Aplicar a carboxiterapia 4. Aplicar o laser vermelho 5. Finalizar com leave in XII. PROTOCOLO COM CORRENTE DIRETA (IONTOFORESE) OU ELETROPORAÇÃO: Função: queda e alopecias 1. Aplicar alta frequência modo direto com afastamento de 5 a 8 minutos no cabelo seco 2. Lavar o cabelo com xampu antiqueda e esfoliar o couro cabeludo 3. Aplicar no couro cabeludo gel de cafeína, centelha asiática ou ginseng. Ocluir por a minutos. Retirar (pode hidratar o fio) 4. Aplicar iontoforese ou eletroporação com ativos estimulantes do crescimento 5. Finalizar com leave in Código POP01 Edição Primeira TERAPIA CAPILAR sem autorização prévia. 11 – CUIDADOS PÓS-PROCEDIMENTO: I. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. II. Entregar uma via do Termo para o cliente. sem autorização prévia. ELABORADO POR: APROVADO POR: DATA DE APROVAÇÃONome: Nome: _____/_____/______ sem autorização prévia</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '034/2026', 'Massagem Modeladora', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>MASSAGEM MODELADORA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de massagem modeladora. Os efeitos da massagem no tecido adiposo podem estar diretamente relacionados à melhora da circulação local, já que a formação de depósitos de gordura ocorre nas regiões em que a circulação é moderada ou lenta</p>"}]}, {"id": "b3", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Para a utilização das mãos, é necessário adequar a pressão imposta sobre cada cliente, adaptando de acordo com cada manobra e movimento. As mãos devem estar relaxadas, soltas e flexíveis para que as manobras sejam bem executadas. O ideal é estabelecer uma sequência determinando tempos e velocidades, iniciando a técnica de maneira lenta, evoluindo para movimentos mais rápidos e intensos, finalizando com a involução da velocidade e pressão. O principal movimento realizado na massagem modeladora é o amassamento, que consiste em comprimir e realizar uma rotação do tecido como um movimento de modelagem, sem soltar a pele, evitando compressões excessivas. Deve ser realizado com as duas mãos associadas, havendo uma alternância dos movimentos. Com a realização do amassamento, é possível gerar incremento da circulação local e remodelamento corporal. Os deslizamentos superficiais são movimentos longos, suaves e rítmicos. Produzem efeito sedativo e atuam nas terminações nervosas e sensitivas da pele. MASSAGEM MODELADORA Os deslizamentos profundos são mais fortes e têm efeito estimulante a depender do ritmo. As massagens são realizadas com o auxílio de cremes e estes podem conter ativos lipolíticos, pois acredita-se que os princípios ativos presentes nos cosméticos utilizados podem ser mais bem absorvidos, penetrando na pele e resultando em ganhos no tratamento</p>"}]}, {"id": "b4", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Equipamento</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada b. As mãos devem estar sempre lavadas, com unhas curtas, sem presença de anéis, pulseiras ou relógios c. Antes de iniciar a técnica, aconselha-se não tocar no cliente com as mãos frias, pode-se aquecê-las e esfregando-as uma na outra com movimentos de fricção Protocolo: Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento Fazer o registro fotográfico pré-procedimento Realizar assepsia na região Aplicar o creme Realizar os movimentos da massagem modeladora MASSAGEM MODELADORA Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e acessórios (ex. bambus, ventosas) utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '035/2026', 'Massagem Relaxante', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>MASSAGEM RELAXANTE</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de massagem relaxante. A massagem relaxante é uma técnica que mescla movimentos firmes e suaves sobre o corpo. Esses movimentos, por sua vez, estimulam a produção de hormônios relaxantes, como a ocitocina, que melhora o estresse e a sensação de medo, assim como a serotonina, que normaliza o humor, os batimentos cardíacos e a sensibilidade em relação à dor. Usando-se de movimentos leves, a massagem relaxante é uma excelente alternativa para o tratamento de dores musculares. Geralmente causadas por estresse, problemas de postura ou movimentos repetitivos</p>"}]}, {"id": "b3", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>É importante que tanto você quanto a pessoa que receberá a massagem não estejam com anéis, correntes, pulseiras e relógios. Sempre pergunte a pessoa que está recebendo a massagem se a pressão do toque está muito forte ou fraco. Somente assim você poderá ter uma noção de como está o toque durante a sua massagem relaxante</p>"}]}, {"id": "b4", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco e luvas</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Óleo ou creme próprio para massagem</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada b. As mãos devem estar sempre lavadas, com unhas curtas, sem presença de anéis, pulseiras ou relógios c. Antes de iniciar a técnica, aconselha-se não tocar no cliente com as mãos frias, pode-se aquecê-las e esfregando-as uma na outra com movimentos de fricção MASSAGEM RELAXANTE Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca com a barriga para baixo 5. Fazer o registro fotográfico pré-procedimento 6. Realizar assepsia na região 7. Aplicar o óleo ou creme 8. Realizar os movimentos da massagem relaxante a. Pés: -Realizar pressão do tendão até a sola do pé - Fazer movimento circular em volta dos tornozelos - Fazer movimento de deslizamento com as duas mãos, deslizando simultaneamente as partes dorsal e plantar do pé - Com o dedo polegar, fazer pressão e movimento circular em toda a região plantar e os dedos -Puxar levemente os dedos dos pés b. Membros inferiores posterior: - Com as duas mãos, deslizar de baixo para cima da panturrilha até a coxa, descer pela lateral - com as duas mãos, deslizar de baixo para cima no sentido da lateral do membro inferior em toda a região - usando a mão toda, fazer movimento circular em toda a extensão do membro - com as mãos sobrepostas, deslizar amassando da panturrilha até a coxa c. Glúteos: - sobre a toalha, fazer pressão com as mãos fechadas, no glúteo d. Costas: - paralelo à coluna, com uma mão de cada lado, de baixo para cima, fazer um deslizamento longo - deslizar com as mãos para a lateral MASSAGEM RELAXANTE - com as duas mãos, fazer movimento de círculos grandes em toda região - com as mãos sobrepostas, fazer um deslizamento longo, amassando um lado das costas de cada vez - com as mãos sobrepostas, deslizar e amassar a lateral das costas e. Ombros e Pescoço: -com as duas mãos, apertar e amassar simultaneamente o trapézio - massageando cada lado do trapézio, um de cada vez, usando as duas mão do mesmo lado, fazer movimento deslizando e torcendo a musculatura - deslizar com as pontas dos dedos do centro das costas até a base do crânio - massagear toda a região do couro cabeludo com as pontas dos dedos, com leve pressão f. Membros inferiores posterior: - com as duas mãos, deslizar de baixo para cima da canela até a coxa, descer pela lateral, suavizar a parte óssea - com as duas mãos, deslizar de baixo para cima no sentido da lateral do membro inferior em toda região - usando a mão toda, fazer movimento circular em toda a extensão do membro g. Barriga: - Com as duas mãos, fazer movimento circular no sentido horário - deslizar com uma mão de cada lado, no sentido da cintura - na cintura, deslizar alternando as mãos h. Membros superiores: -deslizar e amassar com uma mão, toda a região (parte externa do braço) - deslizar e amassar com uma mão, toda a região (parte interna do braço) i. Mãos: -Com os dedos polegares, pressionar e circular toda a região da palma das mãos - Deslizar e puxar cada dedo das mãos j. Peito: - Deslizar com as duas mãos na parte superior do peito, na transversal k. Face: - De baixo para cima, fazer movimentos circulares usando a ponta dos dedos em todo o masseter, suba até as têmporas - com a ponta dos dedos, fazer um movimento de abertura na região da testa, descer para a linha do nariz, parte superior da boca, linha do queixo, e abaixo do queixo até as orelhas, massageando lóbulo e região MASSAGEM RELAXANTE 9. Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas https://www.cursosmassagem.com.br/massagem-relaxante-passo-a-passo .php, em 01/12/2021</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '036/2026', 'Medidor de Fototipo', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>MEDIDOR DE FOTOTIPO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica utilizada para o aparelho medidor de fototipo da pele do cliente. O fototipo é uma classificação que indica a sensibilidade da pele à exposição solar e ajuda a determinar a melhor abordagem para o tratamento da pele</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Avaliar a sensibilidade da pele à exposição solar e determinar o melhor tratamento para pacientes com diferentes tipos de pele. É especialmente útil em clínicas de estética/dermatologia que oferecem tratamentos como peelings químicos e terapia a laser, que podem ser prejudiciais para pacientes com peles mais sensíveis</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAL CONTRA-INDICAÇÃO", "linhas": [{"col1": "", "col2": "<p>Presença de feridas abertas ou infecções na pele na área de teste, bem como em pacientes com sensibilidade conhecida aos materiais utilizados no Medidor</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze ou lenço umedecido Aparelho Medidor de Fototipo</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Realizar a anamnese e registrar na Ficha do Cliente B. Higienização 1. Fazer assepsia das mãos do profissional e do cliente 2. Aplicar o demaquilante no rosto, pescoço e colo do cliente e remover com algodão ou gaze embebida em água ou utilizar o lenço umedecido 3. Fazer esfoliação nas regiões a serem tratadas e massageá-las com movimentos suaves e circulares até o produto formar grumos, secar e sair totalmente. Retirar os resíduos do produto com gazes úmidas ou lenços umedecidos. - A assepsia da região é essencial para não interferir na leitura do medidor. C. Procedimento 4. O profissional deve então posicionar o Medidor de Fototipo de Pele na área que será medida. O Medidor geralmente é posicionado na testa, bochechas, nariz e queixo, que são as áreas mais expostas ao sol. 5. O Medidor de Fototipo de Pele emite uma luz que reflete na pele do paciente. O MEDIDOR DE FOTOTIPO aparelho mede a quantidade de luz refletida e determina o fototipo da pele do paciente. 6. O resultado da leitura é exibido no visor do Medidor de Fototipo de Pele. O profissional deve anotar o resultado na Ficha do Cliente para referência futura</p>"}, {"col1": "<p>D. Referências literárias</p>", "col2": "<p>The Fitzpatrick Skin Type Classification Scale: A Tool for Dermatologic Therapy Planning, Assessment and Research (Thomas B. Fitzpatrick, 1988). Sunscreens: Their Role in Photoprotection (Darlenski R, Fluhr JW), 2010 Photoprotection by Sunscreens with Topical Antioxidants and Systemic Antioxidant Supplements (Nicholas V. Perricone, 2010). Sunscreen Use: Non-Melanoma Skin Cancer and the Importance of Photostability (James</p>"}, {"col1": "<p>Q. Del</p>", "col2": "<p>Rosso, 2013). Photoprotection: A Review of the Current and Future Technologies (R. Ravi, 2017)</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '037/2026', 'Medidor de pele para oleosidade e água', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>MEDIDOR DE PELE PARA OLEOSIDADE E ÁGUA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica utilizada para o aparelho medidor de oleosidade e de água para pele do cliente. O medidor de pele é um aparelho utilizado para medir a oleosidade e a hidratação da pele para avaliar a saúde da pele e determinar quais tratamentos são mais adequados para cada tipo de pele</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>É indicado para avaliar a oleosidade e hidratação da pele e identificar possíveis desequilíbrios ou problemas de saúde da pele</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAL CONTRA-INDICAÇÃO", "linhas": [{"col1": "", "col2": "<ul><li>Pele irritada ou inflamada: O procedimento não é recomendado para pessoas com a pele irritada ou inflamada, pois isso pode interferir nos resultados da medição.</li><li>Pele lesionada: Pessoas com feridas abertas, cortes ou outras lesões na pele devem evitar o procedimento de medidor de pele até que a pele tenha se recuperado completamente</li></ul>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze ou lenço umedecido Aparelho Medidor de oleosidade e hidratação</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Realizar a anamnese e registrar na Ficha do Cliente B. Higienização 1. Fazer assepsia das mãos do profissional e do cliente 2. Limpeza da pele: Antes de iniciar o procedimento, a pele deve ser limpa para remover qualquer sujeira, maquiagem ou resíduos que possam afetar a medição. Aplicar o demaquilante no rosto, pescoço e colo do cliente e remover com algodão ou gaze embebida em água ou utilizar o lenço umedecido 3. Fazer esfoliação nas regiões a serem tratadas e massageá-las com movimentos suaves e circulares até o produto formar grumos, secar e sair totalmente. Retirar os resíduos do produto com gazes úmidas ou lenços umedecidos. - A assepsia da região é essencial para não interferir na leitura do medidor. C. Procedimento 4. Posicionamento do medidor: O medidor de pele é posicionado sobre a pele, geralmente na área do rosto, em contato direto com a superfície da pele. MEDIDOR DE PELE PARA OLEOSIDADE E ÁGUA 5. Leitura da oleosidade: O medidor de pele mede a quantidade de óleo presente na superfície da pele e exibe o resultado em uma escala. Geralmente, uma escala de 0 a 100 é utilizada, em que valores mais altos indicam maior oleosidade da pele. 6. Leitura da hidratação: O medidor de pele também mede a hidratação da pele e exibe o resultado em outra escala. Novamente, valores mais altos indicam uma pele mais hidratada. 7. Análise dos resultados: Com base nos resultados da medição, o profissional pode avaliar o tipo de pele do paciente e recomendar os tratamentos mais adequados para melhorar a saúde da pele. O profissional deve anotar o resultado na Ficha do Cliente para referência futura</p>"}, {"col1": "<p>D. Referências literárias</p>", "col2": "<p>Kim, D. J., &amp; Lee, J. W. (2018). Development of a Skin Hydration and Oil-Meter (SHOM) for the Personalized Skin Care. Journal of Healthcare Engineering, 2018, 1-7. Liu, D., &amp; Nicolosi, R. (2017). Skin Hydration Assessment via Electrical Impedance Spectroscopy. In Electrical Impedance in the Diagnosis of Skin Cancer (pp. 59-71). Springer. Wickett, R. R., &amp; Visscher, M. O. (2006). Structure and function of the epidermal barrier. American Journal of Infection Control, 34(10 Suppl 1), S98-S110</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '038/2026', 'Microagulhamento', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>MICROAGULHAMENTO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de microagulhamento. O microagulhamento, também conhecido como roller ou dermaroller , é o estímulo mecânico à produção de colágeno realizado por meio do rolamento de um cilindro com pequenas agulhas, que ocasionam micro lesões na pele. Além disso, potencializa a permeação de medicamentos e/ou cosméticos de uso tópico. Essa técnica também é conhecida como Terapia de Indução de Colágeno. Também pode ser feito através de um dispositivo eletrônico, que se assemelha a uma caneta, em que um jogo de agulhas descartáveis é colocado na extremidade da caneta</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Rejuvenescimento Rugas Linhas de expressão Acne Cicatriz de acne Melasma Discromias Estrias Potencialização da permeação de produtos Flacidez cutânea (de pele) Alopecia</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Herpes ativa Diabetes Tendência a queloide Alergia ao metal ou ao produto Rosácea ativa Uso de anticoagulantes Gravidez Uso de Roacutan Pele queimada/ bronzeada Processo inflamatório / infecção de pele</p>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>Intervalo entre as sessões de 20 a 30 dias ou de acordo com o objetivo estabelecido</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, jaleco, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>1.Álcool 70% 2.Algodão ou gaze 3.Roller descartável</p>"}]}, {"id": "b8", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Escolha da agulha do roller de acordo com a disfunção estética: Comprimento da agulha: 0,25 a 0,5mm Ação: entrega de drogas, rugas finas, melhoria de brilho e textura MICROAGULHAMENTO Comprimento da agulha: 1,0 a 1,5mm Ação: flacidez cutânea, rugas médias, rejuvenescimento global Comprimento da agulha: 1,5 a 2,0mm Ação: cicatrizes, estrias 4.Dispositivo eletrônico (caneta): A caneta é posicionada em 90° em relação com a pele e o movimento realizado pelo profissional é de arraste ou pontual, dependendo da profundidade da agulha. A caneta conta com diferentes velocidades que variam de acordo com a sensibilidade do cliente e do objetivo a ser atingido</p>"}]}, {"id": "b9", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Anamnese (tirar foto da área a ser tratada) 2. Identificar a região a ser tratada (facial, capilar, corporal) 3. Definir o número de sessões e intervalos entre as sessões Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca durante todo o procedimento 5. Fazer o registro fotográfico pré-procedimento 6. Escolher o roller ou dispositivo eletrônico de acordo com a disfunção estética 7. Aplicar anestésico (deixar agir por 20-30 minutos) 8. Retirar o anestésico 9. Realizar assepsia na região 10. Aplicar a técnica Com o roller : a. Aplicar o roller com pressão moderada 10 vezes na mesma área b. O posicionamento ideal do equipamento nas mãos deve ter controle da força exercida, deve ser concentrado no polegar e o aparelho deve ser manuseado com cautela, sem imprimir força</p>"}]}, {"id": "b10", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Não mude a direção de aplicação enquanto o roller estiver em contato com a pele. Lembre-se que a testa, pálpebras inferiores e a região superior dos lábios são as mais sensíveis Com o dispositivo eletrônico (caneta): a. Realizar a técnica com o auxílio da caneta, conforme manual do fabricante</p>"}]}, {"id": "b11", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Acima de 1,5mm (ou até menos, dependendo do caso) o movimento passa a ser pontual e não de arraste. O movimento de arraste com agulhas mais profundas pode gerar lesão maior e até cicatriz na pele. MICROAGULHAMENTO 11. Aplicar o produto conforme disfunção estética 12. Fazer o registro fotográfico pós-procedimento 13. Descartar o roller OU as agulhas da caneta como lixo perfurocortante (recipiente rígido, conforme Manual de Rotinas e Procedimentos e PGRSS)</p>"}, {"col1": "<p>B. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente</p>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>Terapêutica em Estética, Conceitos e Técnicas, Fábio Borges e Flávia Scorza, Editora Phorte, 2016 Manual de Instrução do equipamento Dermapen Smart</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '039/2026', 'Ozonioterapia (Nota Técnica Anvisa)', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº ________ OZONIOTERAPIA NA ESTÉTICA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de ozonioterapia. Ozonioterapia é uma técnica terapêutica complementar e integrativa, que utiliza a aplicação de uma mistura dos gases oxigênio e ozônio, ou seja, o ozônio medicinal; usada no tratamento de um amplo número de problemas de saúde e disfunções estéticas. A molécula de ozônio é molécula biológica, presente na natureza e produzida pelo organismo sendo que o ozônio medicinal (sempre uma mistura de ozônio e oxigênio), nos seus diversos mecanismos de ação, representa um estimulo que contribui para a melhora de diversas doenças, uma vez que pode ajudar a recuperar de forma natural a capacidade funcional do organismo humano e animal. Forma de aplicação na estética: tópica transdérmica, através de água ozonizada, por meio da vaporização de ozônio. Figura 1: Modelo de vapor de ozônio Figura 2: Modelo de Gerador de Ozônio nº ________ OZONIOTERAPIA NA ESTÉTICA LEGISLAÇÃO SANITÁRIA: Na “NOTA TÉCNICA Nº 43/2022/SEI/GQUIP/GGTPS/DIRE3/ANVISA”, a Anvisa determina apenas algumas indicações de uso aprovadas para o procedimento de ozonioterapia, visto que até o momento, não foram apresentados estudos que comprovem segurança e eficácia do uso da ozonoterapia a partir de equipamentos emissores de ozônio, para fins de aplicação médica ou de indicações de uso diversas daquelas descritas na respectiva Nota Técnica. Assim, sob rol exaustivo, as indicações de uso com segurança e eficácia aprovadas pela ANVISA, para equipamentos médicos emissores de ozônio, são:</p><ul><li>Dentística: tratamento da cárie dental – ação antimicrobiana;</li><li>Periodontia: prevenção e tratamento dos quadros inflamatórios/infecciosos;</li><li>Endodontia: potencialização da fase de sanificação do sistema de canais radiculares; nº ________ OZONIOTERAPIA NA ESTÉTICA</li><li>Cirurgia odontológica: auxílio no processo de reparação tecidual;</li><li>Estética: auxílio à limpeza e assepsia de pele. Fonte: ANVISA, 2022 Nota Técnica disponível no link: https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2022/ozonioterapia-anvisa-esclarece-as-indicacoes-aprovadas-ate-o-momento/sei_anvisa-1922590-nota-tecnica.pdf PRINCIPAIS INDICAÇÕES NA ESTÉTICA: Auxílio à limpeza e assepsia de pele</li></ul>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>A principal contraindicação é deficiência da enzima Glicose-6-Fosfato Desidrogenase (G6PD), conhecida como favismo, em função do risco de hemólise.</li><li>Hipertireoidismo tóxico (status da doença de Basedow)</li><li>Trombocitopenia (contagem de plaquetas menor que 50.000 por microlitro) e distúrbios graves de coagulação</li><li>Instabilidade cardiovascular grave</li><li>Intoxicação aguda por álcool</li><li>Infarto agudo do miocárdio</li><li>Hemorragia aguda</li><li>Durante o status convulsivo</li><li>Hemocromatose nº ________ OZONIOTERAPIA NA ESTÉTICA</li><li>Pacientes que estão recebendo tratamento com cobre ou ferro via intravenosa VAPOR DE ÁGUA E OZONIZAÇÃO DA ÁGUA: A ozonização de água busca saturar com variadas concentrações de ozônio para possibilitar o auxílio à limpeza e assepsia de pele. Uma técnica desenvolvida, e muito utilizada, para a desintoxicação e limpeza da pele, é o vapor com ozônio, que promove assepsia da pele, sendo capaz de se fragmentar, e com tamanho reduzido sua penetração é mais fácil e profunda na pele, promovendo hidratação e reparação tecidual. O ozônio gerado pelo aparelho estimula a circulação local pelo aumento da oxigenação tissular e celular, gerando uma vasodilatação e hiperemia, além de proporcionar nutrição e emoliência da pele, é coadjuvante e eficaz para tratamentos estéticos posteriores. Este aparelho é composto basicamente de um depósito destinado a realizar a evaporação da água através de uma resistência calefatora responsável pela ebulição. O ozônio é liberado por uma “faísca elétrica” de baixa corrente que é disparada no vapor gerado pela ebulição da água dentro do tanque. Sendo assim é possível escolher entre vapor com ozônio ou somente vapor. nº ________ OZONIOTERAPIA NA ESTÉTICA</li></ul>"}]}, {"id": "b4", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>* O intervalo deve ser feita de acordo com a avaliação do profissional</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca e propé Profissional – Touca, jaleco, óculos de proteção, máscara e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Gerador de ozônio medicinal</li><li>Água bidestilada</li><li>Material de assepsia</li><li>Aparelho de vapor de ozônio (inserção do ozônio ao vapor d´água)</li></ul>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada (fazer a anamnese) b. Respeitar a distância mínima de 70cm entre o paciente e o equipamento e de 40cm entre o operador e o equipamento ao longo do tratamento c. Observar, antes de iniciar o atendimento, se o volume de água é adequado e suficiente, já que depois não será possível adicionar mais água fria, pois a caldeira estará fervendo. d. Ligar e testar o aparelho antes de direcioná-lo diretamente ao cliente. Os olhos do cliente devem estar protegidos com algodão úmido. e. Não exceder o tempo de aplicação do vapor com ozônio além de 5’, pois, apesar de o ozônio ser um gás de excelente efeito bactericida e fungicida, seu excesso pode provocar efeitos tóxicos quando inalado por um tempo prolongado, principalmente em gestantes. nº ________ OZONIOTERAPIA NA ESTÉTICA - Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca durante todo o procedimento 5. Fazer o registro fotográfico pré-procedimento 6. Realizar assepsia na região onde será realizado o procedimento 7. Posicionar e ligar o equipamento, respeitando a distância entre o equipamento e o cliente e, também o tempo de duração 8. Dar seguimento aos outros procedimentos pós-limpeza e assepsia da pele 9. Ao final do procedimento, fazer o registro fotográfico Ozonização da água:</p><ul><li>Com a mangueiras de abastecimento (azul) conectada à saída de O3 do equipamento e a entrada de gás do frasco e mangueira de drenagem conectada ao catalizador externo e a saída de gás do frasco, selecione o protocolo desejado ou nº ________ OZONIOTERAPIA NA ESTÉTICA programe de acordo com seu objetivo terapêutico</li><li>Abasteça o frasco com água bidestilada e feche-o, garanta que toda a pedra porosa esteja recoberta de água – Inicie a terapia acionando o botão AUTO FILL</li><li>Ao final do tempo é possível reiniciar o processo de ozonização a fim de manter as concentrações de saturação da água B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</li></ul>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Ministério da Saúde - Portaria nº 702 de 21 de março de 2018. ABOZ – Associação Brasileira de Ozonioterapia. 2022. Disponível em: https://www.aboz.org.br/. Acesso em em 03 Fev. 2023. nº ________ OZONIOTERAPIA NA ESTÉTICA Declaração de Madrid sobre Ozonioterapia (2020) NOTA TÉCNICA Nº 43/2022/SEI/GQUIP/GGTPS/DIRE3/ANVISA, disponível em https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2022/ozonioterapia-anvisa-esclarece-as-indicacoes-aprovadas-ate-o-momento/sei_anvisa-1922590-nota-tecnica.pdf. Acesso em 03 Fev. 2023. BARBOSA, Mariana Santiago; FILHO, José Scarso. Avaliação da concentração da água ozonizada coletada da seringa tríplice em relação ao tempo de armazenamento na cadeira odontológica. I Encontro Científico Internacional de Ozonioterapia, v. 1, n. 1, p. 13, 2019. SÁNCHEZ, Gregorio Martínez. Água ozonizada, antecedentes, usos em medicina y bases preclínicas. Ozone Therapy Global Journal, v. 9, n. 1, p. 5-31, 2019. Ozonioterapia: uma prática integrativa e complementar na estética. Revista Científica Multidisciplinar Núcleo do Conhecimento. Ano. 07, Ed. 05, Vol. 06, pp. 168-196. Maio de 2022. Disponível em:https://www.nucleodoconhecimento.com.br/saude/ozonioterapia. Acesso em 03 Fev. 2023. nº ________ OZONIOTERAPIA NA ESTÉTICA</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '040/2026', 'Panos de limpeza', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº___________ PANOS DE LIMPEZA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Lavar os panos de limpeza, mantendo-os limpos</p>"}]}, {"id": "b3", "subtitulo": "MATERIAIS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<ul><li>Sabão em pó</li><li>Água sanitária</li><li>Luvas de borracha (específica para lavagem de roupas)</li></ul>"}]}, {"id": "b4", "subtitulo": "ATENCÃO", "linhas": [{"col1": "", "col2": "<p>Sempre verificar o Manual do fabricante do saneante para o uso correto do mesmo e sempre verifique se o saneante está devidamente cadastrado na ANVISA (Agência Nacional de Vigilância Sanitária)</p>"}]}, {"id": "b5", "subtitulo": "RESPONSÁVEL", "linhas": [{"col1": "", "col2": "<p>Auxiliar de serviços gerais</p>"}]}, {"id": "b6", "subtitulo": "FREQUÊNCIA", "linhas": [{"col1": "", "col2": "<p>Diariamente e sempre que necessário</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>1. Higienizar as mãos. 2. Calçar as luvas de borracha 3. Levar os panos até o Depósito de Material de Limpeza (DML). 4. Lavar no tanque com água e sabão em pó (colocar em máquina de lavar roupas, se houver). 5. Esfregar até retirar toda sujidade. 6. Colocar em solução de água sanitária, por 30 minutos. 7. Enxaguar abundantemente. 8. Torcer 9. Colocar para secar em local próprio. 10. Lavar as luvas antes de retirá-las 11. Higienizar as mãos. nº___________ PANOS DE LIMPEZA</p>"}]}, {"id": "b8", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Os panos de limpeza devem ser lavados separadamente das demais roupas</p>"}, {"col1": "<p>B. Referência</p>", "col2": "<p>ANVISA (Agência Nacional de Vigilância Sanitária), Serviços Odontológicos, Prevenção e Controle de Riscos, Brasília, 2006. Controle de Infecção e Biossegurança. Procedimentos. CRO/PR</p>"}]}]'::jsonb)
